-- Fictional DP fixtures from purchase_advance_atomic prelude; never target data.
set local role authenticated;
set local request.jwt.claim.role='authenticated';set local request.jwt.claim.sub='d6000000-0000-4000-8000-000000000001';
select pay_purchase_advance_atomic('p05-dp','UM.P05.',5,'d6300000-0000-4000-8000-000000000001','d6400000-0000-4000-8000-000000000001',current_date,400000,'Transfer','d6700000-0000-4000-8000-000000000001',null);
create function pg_temp.check_true(ok boolean,msg text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'Assertion failed: %',msg;end if;end$$;
create function pg_temp.reject(sql text,msg text)returns void language plpgsql as $$begin begin execute sql;exception when others then return;end;raise exception 'Expected rejection: %',msg;end$$;
-- Full edit remains blocked. A new price-only path is required, rather than removing the child guard.
select pg_temp.reject($q$select revise_purchase_order('p05-old-full','d6400000-0000-4000-8000-000000000001',0,'edit','{}','[{"id":"d6500000-0000-4000-8000-000000000001","harga_beli":250000}]','Supplier price changed')$q$,'full edit still rejects DP');
select pg_temp.check_true(to_regprocedure('public.revise_purchase_order_prices(text,uuid,integer,jsonb,text)')is not null,'price-only correction missing for DP-only PO');
create temp table p05_original as select to_jsonb(p)as po,to_jsonb(i)as line from purchase_orders p join purchase_order_items i on i.po_id=p.id where p.id='d6400000-0000-4000-8000-000000000001';
create temp table p05_money as select (select count(*)from journal_entries)as entries,(select count(*)from stock_moves)as moves,(select jsonb_agg(to_jsonb(a)order by a.id)from purchase_advances a)as advances;
create function pg_temp.price_rows(price numeric)returns jsonb language sql as $$select jsonb_build_array(jsonb_build_object('id','d6500000-0000-4000-8000-000000000001','harga_beli',price))$$;
create temp table p05_result as select revise_purchase_order_prices('p05-price','d6400000-0000-4000-8000-000000000001',0,pg_temp.price_rows(250000),'Supplier revised price')as receipt;
select pg_temp.check_true((select total=500000 and revision=1 from purchase_orders where id='d6400000-0000-4000-8000-000000000001'),'price total and revision updated');
select pg_temp.check_true((select to_jsonb(i)-'harga_beli'=o.line-'harga_beli'from purchase_order_items i cross join p05_original o where i.id='d6500000-0000-4000-8000-000000000001'),'exact line identity quantity unit retained');
select pg_temp.check_true((select to_jsonb(p)-'total'-'revision'=o.po-'total'-'revision'from purchase_orders p cross join p05_original o where p.id='d6400000-0000-4000-8000-000000000001'),'parent metadata retained');
select pg_temp.check_true((select receipt=revise_purchase_order_prices('p05-price','d6400000-0000-4000-8000-000000000001',0,pg_temp.price_rows(250000),'Supplier revised price')from p05_result),'retry returns exact receipt before stale revision check');
select pg_temp.check_true((select count(*)=1 from purchase_order_revisions where purchase_order_id='d6400000-0000-4000-8000-000000000001'),'retry one audit');
select pg_temp.reject($q$select revise_purchase_order_prices('p05-price','d6400000-0000-4000-8000-000000000001',0,pg_temp.price_rows(240000),'Supplier revised price')$q$,'changed retry rejected');
select pg_temp.reject($q$select revise_purchase_order_prices('p05-stale','d6400000-0000-4000-8000-000000000001',0,pg_temp.price_rows(240000),'Stale price')$q$,'stale revision rejected');
select pg_temp.reject($q$select revise_purchase_order_prices('p05-under-dp','d6400000-0000-4000-8000-000000000001',1,pg_temp.price_rows(199999.99),'Below DP')$q$,'new total below existing DP rejected');
select pg_temp.reject($q$select revise_purchase_order_prices('p05-forge','d6400000-0000-4000-8000-000000000001',1,'[{"id":"d6500000-0000-4000-8000-000000000001","harga_beli":210000,"qty":99}]','Forged quantity')$q$,'extra quantity cannot enter price-only contract');
select pg_temp.reject($q$select revise_purchase_order_prices('p05-foreign','d6400000-0000-4000-8000-000000000001',1,'[{"id":"d6500000-0000-4000-8000-000000000099","harga_beli":210000}]','Foreign line')$q$,'foreign source rejected');
select pg_temp.reject($q$select revise_purchase_order_prices('p05-duplicate','d6400000-0000-4000-8000-000000000001',1,pg_temp.price_rows(210000)||pg_temp.price_rows(210000),'Duplicate line')$q$,'duplicate source rejected');
select pg_temp.reject($q$select revise_purchase_order_prices('p05-empty','d6400000-0000-4000-8000-000000000001',1,'[]','Empty lines')$q$,'missing source rejected');
select pg_temp.reject($q$select revise_purchase_order_prices('p05-precision','d6400000-0000-4000-8000-000000000001',1,pg_temp.price_rows(210000.001),'Invalid cents')$q$,'subcent money rejected');
select pg_temp.reject($q$select revise_purchase_order_prices('p05-nan','d6400000-0000-4000-8000-000000000001',1,pg_temp.price_rows('NaN'),'Invalid number')$q$,'nonfinite money rejected');
select revise_purchase_order_prices('p05-exact-dp','d6400000-0000-4000-8000-000000000001',1,pg_temp.price_rows(200000),'Exact existing DP');
select pg_temp.check_true((select total=400000 and revision=2 from purchase_orders where id='d6400000-0000-4000-8000-000000000001'),'exact DP cap allowed');
select pg_temp.check_true((select m.entries=(select count(*)from journal_entries)and m.moves=(select count(*)from stock_moves)and m.advances=(select jsonb_agg(to_jsonb(a)order by a.id)from purchase_advances a)from p05_money m),'no journal stock or DP mutation');
reset role;
-- Server authorization and period protection remain effective even when bypassing UI.
set local role authenticated;set local request.jwt.claim.sub='d6000000-0000-4000-8000-000000000003';
select pg_temp.reject($q$select revise_purchase_order_prices('p05-admin','d6400000-0000-4000-8000-000000000001',2,pg_temp.price_rows(250000),'Admin price')$q$,'non-owner rejected');
set local request.jwt.claim.sub='d6000000-0000-4000-8000-000000000001';
set local request.headers='{"x-kamo-operational-branch":"d6100000-0000-4000-8000-000000000002"}';
select pg_temp.reject($q$select revise_purchase_order_prices('p05-branch','d6400000-0000-4000-8000-000000000001',2,pg_temp.price_rows(250000),'Wrong branch')$q$,'operational branch denied');
set local request.headers='{}';
reset role;update accounting_locks set closed_until=current_date where id;
set local role authenticated;
select pg_temp.reject($q$select revise_purchase_order_prices('p05-closed','d6400000-0000-4000-8000-000000000001',2,pg_temp.price_rows(250000),'Closed period')$q$,'closed period rejected');
reset role;update accounting_locks set closed_until=null where id;
-- Any physical receipt, even while PO remains Dipesan, blocks direct price rewriting.
update purchase_order_items set qty_terima=1 where id='d6500000-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.reject($q$select revise_purchase_order_prices('p05-received','d6400000-0000-4000-8000-000000000001',2,pg_temp.price_rows(250000),'Received item')$q$,'received quantity rejected');
reset role;update purchase_order_items set qty_terima=0 where id='d6500000-0000-4000-8000-000000000001';
savepoint p05_child_invoice;
insert into purchase_invoices(no_faktur,po_id,total)values('P05-FICT-INVOICE','d6400000-0000-4000-8000-000000000001',400000);
set local role authenticated;
select pg_temp.reject($q$select revise_purchase_order_prices('p05-invoice','d6400000-0000-4000-8000-000000000001',2,pg_temp.price_rows(250000),'Existing invoice')$q$,'existing invoice rejected');
reset role;rollback to savepoint p05_child_invoice;
savepoint p05_canceled_unproven;
insert into purchase_advances(no_um,supplier_id,po_id,tanggal,jumlah,status)values('UM.P05.UNPROVEN','d6300000-0000-4000-8000-000000000001','d6400000-0000-4000-8000-000000000001',current_date,100,'batal');
set local role authenticated;
select pg_temp.reject($q$select revise_purchase_order_prices('p05-unproven','d6400000-0000-4000-8000-000000000001',2,pg_temp.price_rows(250000),'Unproven DP')$q$,'unproven canceled DP rejected');
reset role;rollback to savepoint p05_canceled_unproven;
create function pg_temp.p05_fail_audit()returns trigger language plpgsql as $$begin raise exception 'Fictional price audit failure';end$$;
create trigger p05_fail_audit before insert on purchase_order_revisions for each row execute function pg_temp.p05_fail_audit();
set local role authenticated;
do $$begin begin perform revise_purchase_order_prices('p05-audit-fail','d6400000-0000-4000-8000-000000000001',2,pg_temp.price_rows(250000),'Audit failure');raise exception 'Expected audit failure';exception when raise_exception then if sqlerrm<>'Fictional price audit failure'then raise;end if;end;end$$;
select pg_temp.check_true((select total=400000 and revision=2 from purchase_orders where id='d6400000-0000-4000-8000-000000000001'),'audit failure rolls back price and revision');
reset role;
select pg_temp.check_true(not exists(select 1 from purchase_order_requests where request_key in('p05-audit-fail','p05-under-dp','p05-received')),'rejected changes leave no receipts');
reset role;
drop trigger p05_fail_audit on purchase_order_revisions;
