select pay_purchase_advance_atomic('p05-cent-b','UM.P05.',5,'d6300000-0000-4000-8000-000000000001','d6400000-0000-4000-8000-000000000004',current_date,0.2,'Transfer','d6700000-0000-4000-8000-000000000001',null);
